#ifndef CAPSTONE_DIET
        // fill in mnemonic & operands
        // find first space or tab
        mnem = insn->mnemonic;
        for (sp = buffer; *sp; sp++) {
                if (*sp == ' '|| *sp == '\t')
                        break;
                if (*sp == '|') // lock|rep prefix for x86
                        *sp = ' ';
                // copy to @mnemonic
                *mnem = *sp;
                mnem++;
        }
